L28_1.m_Talk_KOREA = "관리국의 기함 <color=#ffd34c>인빈서블</color> 덕분에 그 괴물을 쓰러뜨리고 나서 깨달았어."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "管理局の旗艦<color=#ffd34c>インビンシブル</color>のおかげであの化け物を倒してから、悟ったんだ。"
L28_1.m_Talk_ENG = "After bringing down that monster thanks to the Administration's Flagship, <color=#ffd34c>Invincible</color>, I realized something."
L28_1.m_Talk_TWN = "在靠管理局旗艦<color=#ffd34c>無敵號</color>擊倒那隻怪物後，我終於懂了。"
L28_1.m_Talk_DEU = "After bringing down that monster thanks to the Administration's Flagship, <color=#ffd34c>Invincible</color>, I realized something."
L28_1.m_Talk_FRA = "After bringing down that monster thanks to the Administration's Flagship, <color=#ffd34c>Invincible</color>, I realized something."
L29_1 = {}
