L29_1.m_CutScenStrID = "OMEN_FRONTBAY_PROLOGUE"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "JACK_FRONTBAY_NULL_AVERY"
L29_1.m_Talk_KOREA = "이제 우리 힘만으로는 고향을 지킬 수 없다는 것을."
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "これ以上、私たちの力だけでは故郷を守れないということを。"
L29_1.m_Talk_ENG = "We can't protect our home on our own anymore."
L29_1.m_Talk_TWN = "我們已經無法只靠自己的力量守護家鄉。"
L29_1.m_Talk_DEU = "We can't protect our home on our own anymore."
L29_1.m_Talk_FRA = "We can't protect our home on our own anymore."
L30_1 = {}
