L30_1.m_Talk_ENG = "Bonny must have known that too. That's why she chose what she did."
L30_1.m_Talk_TWN = "寶妮也是明白這點，才做出那樣的選擇吧。"
L30_1.m_Talk_DEU = "Bonny must have known that too. That's why she chose what she did."
