L48_1.m_CharStrID = "JACK_FRONTBAY_NULL_AVERY"
L48_1.m_Pos = "C"
L48_1.m_Talk_KOREA = "사람들이 과거의 망령에 사로잡히지 않도록, 나는 얼굴을 가리고, 목소리를 변조하여 살아갈 생각이야."
L48_1.m_fTalkTime = 0.03
L48_1.m_Talk_JPN = "人々が過去の亡霊に囚われないよう、私は顔を隠し、声を変えて今後生きていくつもりさ。"
L48_1.m_Talk_ENG = "I'm gonna hide my face and change my voice, so people don't cling to the ghosts of the past."
L48_1.m_Talk_TWN = "為了不讓大家被過去的亡靈束縛，我會遮住自己的臉、改變聲音活下去。"
L48_1.m_Talk_DEU = "I'm gonna hide my face and change my voice, so people don't cling to the ghosts of the past."
L48_1.m_Talk_FRA = "I'm gonna hide my face and change my voice, so people don't cling to the ghosts of the past."
